mapper.select:
SELECT *
FROM TB_FILE
WHERE BOARD_ID = #{boardId}
  AND MENU_CD = #{menuCd}
ORDER BY REG_DT DESC

SELECT *
FROM TB_FILE
WHERE FILE_ID = #{fileId}
  AND MENU_CD = #{menuCd}
  AND BOARD_ID = #{boardId}
ORDER BY REG_DT DESC

mapper.insert:
INSERT INTO TB_FILE
( BOARD_ID
, MENU_CD
, FILE_NEW_NAME
, FILE_NAME
, FILE_SIZE
, FILE_PATH
, FILE_TYPE
, FILE_EXTENSION
, REG_ID
, REG_DT)
VALUES ( #{boardId}
       , #{menuCd}
       , #{fileNewName}
       , #{fileName}
       , #{fileSize}
       , #{filePath}
       , #{fileType}
       , #{fileExtension}
       , #{regId}
       , now())

mapper.delete:
DELETE FROM
    TB_FILE
WHERE 
	BOARD_ID = #{boardId}
AND 
	MENU_CD = #{menuCd}
